:root {
  --color-accent: #93652B;
  --color-dark: #806329;
  --color-gold-light: #E8C789;
  --color-ivory: #FFF9EF;
  --background-premium:
    radial-gradient(ellipse at 12% 0%, rgba(232, 199, 137, 0.22), transparent 55%),
    radial-gradient(ellipse at 100% 100%, rgba(155, 100, 52, 0.3), transparent 65%),
    linear-gradient(135deg, #715424 0%, #49351F 48%, #241C18 100%);
  --background-gold: linear-gradient(120deg, #93652B 0%, #7F5424 55%, #62401F 100%);
  --color-white: #FFFFFF;
  --color-title: #373E4C;
  --color-text: #888E92;
  --font-body: 'Montserrat', sans-serif;
  --font-heading: 'Poppins', sans-serif;
}

